const t = $('When Executed by Another Workflow').item.json;
const MAP_TIPO = {
 'prueba de manejo':'Prueba de manejo','prueba':'Prueba de manejo','test drive':'Prueba de manejo','manejo':'Prueba de manejo',
 'visita':'Visita a sucursal','visita a sucursal':'Visita a sucursal','sucursal':'Visita a sucursal','presencial':'Visita a sucursal',
 'llamada':'Llamada','telefono':'Llamada','call':'Llamada',
 'financiamiento':'Cita de financiamiento','credito':'Cita de financiamiento','crédito':'Cita de financiamiento','cita de financiamiento':'Cita de financiamiento',
 'videollamada':'Videollamada','video':'Videollamada'
};
const tipo = MAP_TIPO[String(t.tipo_cita||'').trim().toLowerCase()] || 'Visita a sucursal';
const DUR = {'Prueba de manejo':45,'Visita a sucursal':30,'Llamada':20,'Cita de financiamiento':45,'Videollamada':30};
const duracion_min = DUR[tipo] || 30;

const fecha=String(t.fecha||'').trim(), hora=String(t.hora||'').trim();
const fechaOk=/^\d{4}-\d{2}-\d{2}$/.test(fecha), horaOk=/^\d{2}:\d{2}$/.test(hora);
if(!fechaOk||!horaOk){ return [{json:{ok:false,datos_invalidos:true,tipo_cita:tipo,mensaje_agente:'No pude leer bien la fecha u hora. ¿Me confirmas el día (por ejemplo 20 de junio) y la hora?'}}]; }

const fecha_hora_inicio=`${fecha}T${hora}:00-06:00`;
const inicio=new Date(fecha_hora_inicio);
const desde=new Date(inicio.getTime()-60*60000).toISOString();
const hasta=new Date(inicio.getTime()+60*60000).toISOString();
const [yy,mm,dd]=fecha.split('-');
const telDigits=String(t.user_id_canal||'').replace(/[^0-9]/g,'');
const cita_id=`${dd}${mm}${yy}-${telDigits}`;

return [{json:{ ok:true, tipo_cita:tipo, duracion_min, fecha, hora, fecha_hora_inicio,
  ventana_desde:desde, ventana_hasta:hasta, cita_id, user_id_canal:t.user_id_canal,
  lead_id:t.lead_id||null, modelo:t.modelo||'', notas:t.notas||'', sucursal_id:t.sucursal_id||'' }}];

const prep = $('Code · Validate & Prep1').first().json;

// recId de la sucursal destino
let sucRec=null;
try { const s=$('Airtable · Get Sucursal1').first().json; if(s && s.id) sucRec=s.id; } catch(e){}

let rows = []; try { rows = $('Airtable · Check Conflicts1').all().map(i=>i.json).filter(r=>r && r.id); } catch(e){}

// El filtro por sucursal NO puede ir en filterByFormula: ARRAYJOIN() de un campo
// link devuelve el PRIMARY (ej. "MOT"), no el recId, asi que FIND(recId, ...) da
// siempre 0 y NINGUNA cita se contaba como conflicto. El API si entrega el link
// como array de recIds, por eso se compara aqui.
const F = r => (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{});
const conflictos = rows.filter(r => {
  const f = F(r);
  const suc = Array.isArray(f.sucursal) ? f.sucursal : [];
  return sucRec ? suc.includes(sucRec) : true;   // sin sucursal resuelta, se es conservador
});

if (conflictos.length > 0) {
  const base = new Date(prep.fecha_hora_inicio);
  const fmt = (dt)=> dt.toLocaleString('es-MX',{timeZone:'America/Merida',weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',hour12:true});
  const alt1 = new Date(base.getTime()+2*3600*1000);
  const alt2 = new Date(base.getTime()+24*3600*1000);
  return [{ json: { ok:false, ocupado:true, tipo_cita:prep.tipo_cita,
    mensaje_agente:`Ese horario ya está ocupado en esa sucursal. Te propongo: ${fmt(alt1)} o ${fmt(alt2)}. ¿Cuál te acomoda?` } }];
}
return [{ json: { ...prep, libre:true } }];

function F(r){ return (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{}); }
const v = $('Code · Validate & Prep1').first().json;
let lead={}; try{ lead = F($('Airtable · Get Lead1').first().json); }catch(e){}
let sucFromLookup=null; try{ const s=$('Airtable · Get Sucursal1').first().json; if(s && s.id) sucFromLookup=s.id; }catch(e){}

// Guarda-espaldas: si el lead YA tiene sucursal guardada en el CRM, esa manda sobre
// el sucursal_id que mando el LLM. Evita que una ciudad con varias sucursales
// (Merida, Campeche) termine agendando con el asesor equivocado.
const sucLead = (lead.sucursal_interes && lead.sucursal_interes[0]) || null;
let sucursalOverride = false;
if (sucLead && sucLead !== sucFromLookup) { sucFromLookup = sucLead; sucursalOverride = true; }

// --- Elegir asesor: sucursal -> continuidad con el lead -> primero estable ---
// El filtro por sucursal se hace aqui y no con filterByFormula: ARRAYJOIN() de un
// link devuelve el primary, no el recId. Antes esto no matcheaba nunca y la cita
// se creaba sin asesor.
let candidatos=[];
try { candidatos = $('Airtable · Get Asesor1').all().filter(x=>x.json && x.json.id)
        .map(x=>{ const f=F(x.json); return { id:x.json.id, ...f }; }); } catch(e){}

let pool = sucFromLookup
  ? candidatos.filter(x => Array.isArray(x.sucursal) && x.sucursal.includes(sucFromLookup))
  : [];
if (!pool.length) pool = candidatos.filter(x => String(x.asesor_id||'').trim().toUpperCase()==='CAP-LN');
if (!pool.length) pool = candidatos.slice();
pool.sort((x,y)=>String(x.asesor_id||'').localeCompare(String(y.asesor_id||'')));

// Continuidad: si el lead ya trae asesor del handoff, la cita va con el mismo.
let elegido=null;
const prevAsesor = (lead.asesor_asignado && lead.asesor_asignado[0]) || null;
if (prevAsesor) elegido = pool.find(x=>x.id===prevAsesor) || null;
if (!elegido) elegido = pool[0] || null;

const asesorRec = elegido ? { id: elegido.id } : {};
const a = elegido || {};

const dur = v.duracion_min||30;
const inicioEpoch = new Date(v.fecha_hora_inicio).getTime();
function toMX(ms){ return new Date(ms-6*3600000).toISOString().replace('.000Z','')+'-06:00'; }
const fecha_hora_fin = toMX(inicioEpoch + dur*60000);

const leadEmail=lead.email||'', leadNombre=lead.nombre||v.user_id_canal;
const asesorEmail=a.email||'', asesorNombre=a.nombre||'Por asignar';

// --- Datos para las notificaciones (Slack al asesor + mensaje al agente) ---
const asesorSlack = String(a.slack_id||'').trim();
const asesorTel   = String(a.telefono||'').trim();
const asesorCod   = String(a.asesor_id||'').trim();

let S = {};
try { const s=$('Airtable · Get Sucursal1').first().json; S = F(s); } catch(e){}
const sucNombre  = S.nombre || v.sucursal_id || 'Por definir';
const sucDir     = S.direccion || '';
const sucMaps    = S.google_maps || '';
const sucHorario = S.horario || '';
const sucTel     = S.whatsapp_publico || S.telefono || '';

// Perfil del lead, para que el asesor llegue con contexto y no de cero.
const perfil = [
  lead.ciudad     ? `Ciudad: ${lead.ciudad}` : '',
  lead.colonia    ? `Colonia: ${lead.colonia}` : '',
  lead.uso_principal        ? `Uso: ${lead.uso_principal}` : '',
  lead.forma_pago_preferida ? `Pago: ${lead.forma_pago_preferida}` : '',
  lead.enganche_disponible  ? `Enganche: $${Number(lead.enganche_disponible).toLocaleString('es-MX')}` : '',
  lead.presupuesto_declarado? `Presupuesto: $${Number(lead.presupuesto_declarado).toLocaleString('es-MX')}` : '',
  lead.financiera_elegida   ? `Financiera: ${lead.financiera_elegida}` : '',
  lead.lead_score !== undefined && lead.lead_score !== null ? `Score: ${lead.lead_score}` : '',
].filter(Boolean).join(' · ');

const fechaLegible = new Date(v.fecha_hora_inicio).toLocaleString('es-MX',
  {timeZone:'America/Merida',weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',hour12:true});

const attendees=[]; if(asesorEmail)attendees.push(asesorEmail); if(leadEmail)attendees.push(leadEmail);
const summary=`${v.tipo_cita} · ${leadNombre} · ${v.modelo||'moto'}`;
const description=[`Tipo: ${v.tipo_cita}`,`Lead: ${leadNombre} (${v.user_id_canal})`,`Modelo de interés: ${v.modelo||'N/D'}`,`Sucursal: ${v.sucursal_id||'N/D'}`,`Asesor: ${asesorNombre}`, v.notas?`Notas: ${v.notas}`:''].filter(Boolean).join('\n');

const sucursal_rec = sucFromLookup || (Array.isArray(a.sucursal)&&a.sucursal[0]) || null;

return [{json:{ fecha_hora_inicio:v.fecha_hora_inicio, fecha_hora_fin, attendees, summary, description,
  asesor_id: asesorRec.id||null, asesor_email:asesorEmail, asesor_nombre:asesorNombre,
  asesor_slack_id: asesorSlack, asesor_telefono: asesorTel, asesor_codigo: asesorCod,
  tiene_slack: !!asesorSlack,
  lead_email:leadEmail, lead_nombre:leadNombre, lead_perfil: perfil,
  lead_telefono: String(v.user_id_canal||'').replace(/[^0-9]/g,''),
  sucursal_rec, sucursal_override: sucursalOverride,
  sucursal_nombre: sucNombre, sucursal_direccion: sucDir, sucursal_maps: sucMaps,
  sucursal_horario: sucHorario, sucursal_telefono: sucTel,
  fecha_legible: fechaLegible, duracion_min: dur }}];

const v  = $('Code · Validate & Prep1').first().json;
const ev = $('Code · Prep Event1').first().json;

// Mensaje que el AGENTE le repite al cliente. Va en burbujas (línea en blanco =
// burbuja nueva), con lo que el cliente necesita para presentarse: cuándo, dónde
// y con quién. Sin datos internos (nada de score, IDs ni códigos).
const b1 = `¡Listo! Te agendé tu ${v.tipo_cita.toLowerCase()} para el ${ev.fecha_legible}`
         + (ev.modelo || v.modelo ? ` con la ${v.modelo}` : '') + '.';

const partes = [];
if (ev.sucursal_nombre)    partes.push(`Es en ${ev.sucursal_nombre}`);
if (ev.sucursal_direccion) partes.push(ev.sucursal_direccion);
const b2 = partes.length ? partes.join(', ') + '.' : '';

const b3 = (ev.asesor_nombre && ev.asesor_nombre !== 'Por asignar')
  ? `Te va a atender ${ev.asesor_nombre}; él te confirma por aquí.`
  : `Un asesor de la sucursal te confirma por aquí.`;

const b4 = ev.sucursal_maps ? `Aquí te dejo la ubicación: ${ev.sucursal_maps}` : '';
const b5 = ev.lead_email ? 'Te llega también la invitación por correo.' : '';

const mensaje = [b1, b2, b3, b4, b5].filter(Boolean).join('\n\n');

return [{ json: {
  ok: true,
  creada: true,
  cita_id: v.cita_id,
  tipo_cita: v.tipo_cita,
  fecha_legible: ev.fecha_legible,
  asesor: ev.asesor_nombre,
  asesor_notificado: ev.tiene_slack,
  sucursal: ev.sucursal_nombre,
  sucursal_direccion: ev.sucursal_direccion,
  mensaje_agente: mensaje,
} }];

